import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { UserMain } from './user-main/user-main';

const routes: Routes = [
  {
    path: '', component: UserMain, children: [
      { path: 'signin', loadComponent: () => import('./components/signin/signin.component').then((m) => m.SigninComponent) },
      { path: 'signup', loadComponent: () => import('./components/signup/signup.component').then((m) => m.SignupComponent) },
      { path: 'support', loadComponent: () => import('./components/user-support/user-support').then((m) => m.UserSupport) },
      { path: 'profile', loadComponent: () => import('./components/user-profile/user-profile').then((m) => m.UserProfile) },
      { path: 'settings', loadComponent: () => import('./components/user-settings/user-settings').then((m) => m.UserSettings) },
      {
        path: 'dashboard', loadComponent: () => import('./components/user-dashboard/user-dashboard').then((m) => m.UserDashboard), children: [
          {path:'',  redirectTo: 'devotional', pathMatch: 'full' },//temp
          { path: 'devotional', loadChildren: () => import('../devotional/devotional-module').then((m) => m.DevotionalModule) }
        ]
      },


    ]
  },

];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class UserRoutingModule { }
